class Solution {
public:
    bool hasAllCodes(string s, int k) {
        int n = s.size();
        int need = 1 << k;
        if (n - k + 1 < need) return false;
        vector<bool> seen(need, false);
        int count = 0;
        int mask = need - 1;
        int hash = 0;
        for (int i = 0; i < k; i++) {
            hash = ((hash << 1) | (s[i] - '0')) & mask;
        }
        if (!seen[hash]) {
            seen[hash] = true;
            count++;
        }
        for (int i = k; i < n; i++) {
            hash = ((hash << 1) | (s[i] - '0')) & mask;
            if (!seen[hash]) {
                seen[hash] = true;
                count++;
            }
        }
        return count == need;
    }
};
